import { complete } from '@projexlight/sdk-ai-gateway';
const result = await complete({
  tenant_id, persona_id, intent: 'blueprint-clarify',
  messages: [{ role: 'user', content: 'I want a claims-intake workflow with photo evidence' }],
  max_tokens: 1000,
});
console.log(result.message.content, result.usage);

import { addRedactionRule, complete } from '@projexlight/sdk-ai-gateway';
await addRedactionRule({
  tenant_id, rule_id: 'ssn',
  pattern: '\\b\\d{3}-\\d{2}-\\d{4}\\b',
  replacement_strategy: 'reversible-token',
});
// Now every complete() call has SSNs in the prompt replaced with tokens before the LLM sees them, and reversed in the response.

// route_rule rows:
// { intent: 'blueprint-clarify', primary: 'anthropic/claude-sonnet', fallback_on_cost_cap: 'anthropic/claude-haiku' }
// On budget exhaustion the gateway switches automatically.

// Health probe spots the degradation; flips ai_gateway.provider.health_status
// Next complete() call uses the fallback in the route_rule's chain.
// Emits ai-gateway.provider.degraded.v1.

import { stream } from '@projexlight/sdk-ai-gateway';
for await (const delta of stream({
  tenant_id, persona_id, intent: 'cloud-builder-chat',
  messages: [...],
})) {
  process.stdout.write(delta.token);
}
